'use strict';
(()=>{
const C=window.TEMPLADO,K='ludaria_templado_pares_v1',$=id=>document.getElementById(id),N=C.pages.length;
const fresh=()=>({version:1,page:0,visited:[0],fields:{},reviews:[{levels:Array(7).fill(''),comments:Array(7).fill(''),strength:'',suggestion:''},{levels:Array(7).fill(''),comments:Array(7).fill(''),strength:'',suggestion:''}],ceremony:false});
let s=fresh(),ok=true,opener=null,flash='';
try{const old=JSON.parse(localStorage.getItem(K)||'null');if(old?.version===1){s.page=Number.isInteger(old.page)&&old.page>=0&&old.page<N?old.page:0;s.visited=Array.isArray(old.visited)?old.visited.filter(x=>Number.isInteger(x)&&x>=0&&x<N):[0];for(const k in C.fields)if(typeof old.fields?.[k]==='string')s.fields[k]=old.fields[k].slice(0,6000);for(let r=0;r<2;r++){const v=old.reviews?.[r];if(v){for(let i=0;i<7;i++){s.reviews[r].levels[i]=C.levels.includes(v.levels?.[i])?v.levels[i]:'';s.reviews[r].comments[i]=typeof v.comments?.[i]==='string'?v.comments[i].slice(0,6000):'';}for(const k of ['strength','suggestion'])if(typeof v[k]==='string')s.reviews[r][k]=v[k].slice(0,6000);}}s.ceremony=old.ceremony===true;}}catch(e){ok=false;}
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(a,txt,attrs='',secondary=false)=>`<button class="button ${secondary?'secondary':''}" data-action="${a}" ${attrs}>${txt}</button>`;
const field=k=>`<label class="field">${C.fields[k]}<textarea data-field="${k}" maxlength="6000" rows="3">${esc(s.fields[k])}</textarea></label>`;
function save(){try{localStorage.setItem(K,JSON.stringify(s));}catch(e){ok=false;$('toast').hidden=false;$('toast').textContent='Guardado local restringido. Conserva el registro visible antes de cerrar.';}}
const scene=(n,body)=>`<section class="scene"><div class="scene-content wide"><div class="section-title"><div><span class="eyebrow">FORJA DEL ARQUITECTO · FORJADOR ONDAL · CREACIÓN</span><h2>${C.pages[n][0]}</h2></div><span class="time-label">${C.pages[n][1]} min · en clase</span></div><p class="lead">${C.pages[n][2]}</p>${body}<p class="note product">Producto: ${C.pages[n][3]}</p></div></section>`;
const form=r=>`<p class="note">Anexo H · criterios y niveles conservados. Marca solo lo que observaste; un campo vacío permanece pendiente.</p>${field('pair'+(r+1))}<div class="review-cards">${C.criteria.map((c,i)=>`<article class="review-card"><h3>${i+1}. ${c}</h3><label>Nivel · criterio ${i+1}<select data-review="${r}" data-index="${i}" data-kind="level"><option value="">Sin marcar</option>${C.levels.map(l=>`<option ${s.reviews[r].levels[i]===l?'selected':''}>${l}</option>`).join('')}</select></label><label>Comentario · criterio ${i+1}<textarea maxlength="6000" rows="2" data-review="${r}" data-index="${i}" data-kind="comment">${esc(s.reviews[r].comments[i])}</textarea></label></article>`).join('')}</div><div class="work-grid">${['strength','suggestion'].map((k,i)=>`<label class="field">${i?'Una sugerencia concreta de mejora':'Mayor fortaleza del diseño revisado'}<textarea rows="3" maxlength="6000" data-review="${r}" data-kind="${k}">${esc(s.reviews[r][k])}</textarea></label>`).join('')}</div><div class="actions">${button('record','Conservar esta revisión')}</div><p class="note">No se envía al autor desde el HTML. Comparte el registro por el canal real indicado.</p>`;
function page(n){switch(n){case 0:return `<section class="scene"><div class="cover-content"><span class="eyebrow">MISIÓN SECUNDARIA 2 · MÓDULO 3 · SESIÓN 10</span><h1 class="cover-title">El Templado<br><span>entre Pares</span></h1><p class="lead">Dos miradas para afinar el diseño.<br>Una decisión propia para darle nueva forma.</p><div class="cover-meta"><span class="small-line"></span><span>Forja del Arquitecto · Forjador Ondal</span></div><div class="actions">${button('begin','Comenzar el intercambio')}</div><p class="note">90 minutos sincrónicos · Sin carga autónoma adicional</p></div></section>`;
case 1:return scene(n,`<div class="work-grid">${field('project')}<article class="panel"><h3>Un protocolo compartido</h3><p>Leer el diseño → observar con la pauta → comentar con una evidencia → compartir con su autor.</p><p class="note">El autor recibe dos revisiones distintas y decide cómo ajustar su canvas. La revisión humana conduce el proceso.</p></article></div><div class="actions">${button('resources','Canvas y canales','',true)}${button('pauta','Consultar Anexo H','',true)}</div>`);
case 2:return scene(n,`<div class="canvas-grid">${C.criteria.map((c,i)=>`<button class="canvas-tile" data-action="criterion" data-index="${i}"><span class="eyebrow">CRITERIO ${i+1}</span><p>${c}</p></button>`).join('')}</div><p class="note">Niveles: Se observa · Parcial · No se observa. Mayor fortaleza y una sugerencia concreta. Sin suma ni nota automática.</p><div class="actions">${button('pauta','Ver pauta completa')}${button('practice','Ensayar un comentario','',true)}</div>`);
case 3:case 4:return scene(n,`<div class="split"><article class="panel"><h3>Ronda ${n-2}</h3><p>1. Lee el canvas.<br>2. Recorre los siete criterios.<br>3. Marca un nivel y comenta.<br>4. Destaca fortaleza y mejora.<br>5. Comparte con el autor.</p></article><article class="panel"><h3>Una observación útil</h3><p>Relaciona tu comentario con lo que se ve en el diseño. Pregunta cuando falte información; evita valorar a la persona.</p><div class="actions">${button('review','Abrir pauta de la ronda',`data-review="${n-3}"`)}${button('pauta','Consultar los criterios','',true)}</div></article></div><p class="note">La pauta editable está en una ventana para leer cada criterio con espacio. Puedes volver y conservar pendientes.</p>`);
case 5:return scene(n,`<div class="work-grid">${field('received1')}${field('received2')}</div><p class="note">Copia o sintetiza observaciones reales. Deja pendiente lo que aún no recibiste y solicita apoyo al facilitador.</p>`);
case 6:return scene(n,`<div class="work-grid">${field('change')}${field('reason')}</div><p class="note">Precisa dónde quedó el cambio en tu canvas. Guardar este texto no modifica el archivo externo.</p><div class="actions">${button('resources','Abrir recursos','',true)}</div>`);
case 7:return scene(n,`<div class="work-grid">${field('next')}<article class="panel"><h3>Tu registro reúne</h3><p>Las dos pautas realizadas, las dos miradas recibidas y la decisión de ajuste. No asigna notas ni verifica entregas.</p><div class="actions">${button('record','Ver mi registro completo')}${button('notebook','Revisar mi bitácora','',true)}</div></article></div>`);
case 8:return scene(n,`<div class="split"><div><span class="eyebrow">CIERRE DEL MÓDULO 3</span><h3 class="ceremony-title">El Fragmento III<br>vuelve al Orbe.</h3><p class="lead">${s.ceremony?'Cierre narrativo representado en este dispositivo.':'Espera la indicación del facilitador para representar el cierre.'}</p><div class="actions">${button('ceremony','Representar el cierre acompañado')}${button('record','Conservar el registro','',true)}</div></div><article class="panel"><h3>El Santuario del Espejo</h3><p>En El Reflejo del Diseño construiremos criterios sistemáticos para evaluar experiencias gamificadas.</p><p class="note">Este cierre local no acredita atributos ni verifica que se recibieran revisiones. El facilitador confirma el recorrido real.</p></article></div>`);}}
function render(focus=false){document.body.classList.toggle('is-cover',s.page===0);$('stage').innerHTML=page(s.page);$('page-count').textContent=`${s.page+1} / ${N}`;$('previous').disabled=s.page===0;$('next-label').textContent=s.page===N-1?'Mi registro':'Siguiente';$('route-dots').innerHTML=C.pages.map((p,i)=>`<button class="route-dot ${s.visited.includes(i)?'visited':''} ${s.page===i?'current':''}" data-action="go" data-page="${i}" aria-label="Pantalla ${i+1}: ${p[0]}" ${s.page===i?'aria-current="step"':''}></button>`).join('');if(focus)$('stage').focus({preventScroll:true});}
function go(n){if(n<0||n>=N||!Number.isInteger(n))return;if($('modal').open)$('modal').close();s.page=n;if(!s.visited.includes(n))s.visited.push(n);save();history.replaceState(null,'',`#pantalla-${n+1}`);render(true);window.scrollTo(0,0);}
function modal(title,body){if(!$('modal').open)opener=document.activeElement;$('modal-body').innerHTML=`<h2 id="modal-title" tabindex="-1">${title}</h2>${body}`;if(!$('modal').open)$('modal').showModal();$('modal-title').focus();}
function close(){const old=opener;$('modal').close();render();if(old?.isConnected)old.focus();else $('stage').focus();}
function pauta(){modal('Anexo H · Pauta de coevaluación',`<p>Cada buscador revisa el canvas de dos compañeros, marca el nivel observado, añade un comentario breve y entrega el registro al autor del diseño revisado.</p><ol class="reward-list">${C.criteria.map(c=>`<li>${c}</li>`).join('')}</ol><p>Se observa · Parcial · No se observa</p><p>Mayor fortaleza del diseño revisado<br>Una sugerencia concreta de mejora</p><p class="note">Fuente: tesis, Anexo H, pp.65–66. Sin pesos o puntajes agregados.</p>`);}
function recordText(){let t='BUSCADORES DE LA GAMIFICACIÓN PERDIDA\nEl Templado entre Pares · Sesión 10\n';for(let r=0;r<2;r++){t+=`\nREVISIÓN REALIZADA ${r+1}\n${s.fields['pair'+(r+1)]||'Pendiente'}\n`;C.criteria.forEach((c,i)=>t+=`${i+1}. ${c}\nNivel: ${s.reviews[r].levels[i]||'Sin marcar'}\nComentario: ${s.reviews[r].comments[i]||'Pendiente'}\n`);t+=`Mayor fortaleza del diseño revisado: ${s.reviews[r].strength||'Pendiente'}\nUna sugerencia concreta de mejora: ${s.reviews[r].suggestion||'Pendiente'}\n`;}for(const k in C.fields)if(!k.startsWith('pair'))t+=`\n${C.fields[k]}\n${s.fields[k]||'Pendiente'}\n`;return t+`\nCierre narrativo local: ${s.ceremony?'Representado':'Pendiente'}\nSin envío, recepción verificada ni calificación automática.\n\nFUENTES\n${C.source}\n${C.theory}`;}
function record(){modal('Registro del Templado',`<p>Selecciona, copia o descarga para compartir por el canal real. ${ok?'Guardado local disponible.':'Guardado restringido; conserva este texto.'}</p><label class="field">Registro completo<textarea id="export-text" readonly rows="16">${esc(recordText())}</textarea></label><div class="actions">${button('copy','Copiar registro')}${button('download','Descargar TXT','',true)}</div><p class="note">No se envía desde el HTML. Si el marco restringe descarga o copia, selecciona el texto manualmente.</p>`);}
function practice(){modal('Ensayar un comentario',`<p>Caso ficticio: la misión propone justificar una explicación, pero solo menciona terminar la tarea. ¿Qué comentario ayuda a precisar el criterio 2?</p>${button('practice-a','«Muy bien, me gustó»')}${button('practice-b','«¿Qué acción observable mostrará que el estudiante justificó su explicación?»')}<div id="practice-feedback" role="status">${flash}</div><p class="note">Ensayo didáctico propio. No es un criterio extra ni una calificación. Reintentos sin penalización.</p>`);}
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.field){s.fields[t.dataset.field]=t.value;save();}if(t.dataset.review!==undefined){const r=Number(t.dataset.review),i=Number(t.dataset.index),k=t.dataset.kind;if(k==='level')s.reviews[r].levels[i]=t.value;else if(k==='comment')s.reviews[r].comments[i]=t.value;else s.reviews[r][k]=t.value;save();}});
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;switch(el.dataset.action){case 'begin':go(1);break;case 'go':go(Number(el.dataset.page));break;case 'close':close();break;case 'map':modal('Los pasos del Templado',`<p>Navegación libre; el facilitador conduce la clase.</p><div class="modal-grid">${C.pages.map((p,i)=>button('go',`${i+1}. ${p[0]}`,`data-page="${i}"`,true)).join('')}</div>${button('reset-ask','Reiniciar esta misión','',true)}`);break;

case 'sources':modal('Fuentes y límites',`<p>${C.source}</p><p>${C.theory}</p><p><a href="https://strathprints.strath.ac.uk/3235/" target="_blank" rel="noopener">Registro y resumen de autor · Nicol y Macfarlane-Dick</a></p><p>Se verificaron el resumen y los datos del artículo en el repositorio institucional; no se afirma lectura del texto completo. Este modelo propone prácticas de feedback para apoyar la autorregulación. No prueba resultados de este taller. Pauta del Anexo H conservada; protocolo operativo y ensayo: elaboración propia.</p>`);break;
case 'pauta':pauta();break;case 'criterion':modal('Criterio '+(Number(el.dataset.index)+1),`<p>${C.criteria[Number(el.dataset.index)]}</p><p>Se observa · Parcial · No se observa. Acompaña el nivel con un comentario sobre el canvas.</p><p class="note">Anexo H, pp.65–66. Sin puntuación añadida.</p>`);break;
case 'review':modal('Pauta · ronda '+(Number(el.dataset.review)+1),form(Number(el.dataset.review)));break;
case 'notebook':modal('Mi bitácora editable',`<div class="work-grid">${Object.keys(C.fields).map(field).join('')}</div><div class="actions">${button('review','Pauta de ronda 1','data-review="0"')}${button('review','Pauta de ronda 2','data-review="1"')}${button('record','Ver registro completo')}</div>`);break;case 'record':record();break;
case 'resources':modal('Canvas y canales',['canvasExterno','coevaluacionExterna'].map(k=>{const u=window.TEMPLADO_CONFIG?.[k];return typeof u==='string'&&/^https:\/\//.test(u)?`<p><a href="${esc(u)}" target="_blank" rel="noopener">Abrir ${k==='canvasExterno'?'canvas':'coevaluación'} externo</a></p>`:'<p>Enlace externo pendiente. Puedes usar las pautas y la bitácora locales, y compartir por el canal indicado por el facilitador.</p>';}).join('')+button('notebook','Abrir bitácora local'));break;
case 'practice':practice();break;case 'practice-a':flash='El comentario expresa agrado, pero no concreta qué acción observar. Vuelve a intentar o conversa la pregunta con el facilitador.';practice();break;case 'practice-b':flash='La pregunta conecta el comentario con una acción observable y ayuda al autor a precisar su diseño. La decisión posterior corresponde al autor.';practice();break;
case 'ceremony':modal('Cierre acompañado',`<p>Representa el Fragmento III cuando el facilitador indique que corresponde cerrar el módulo. No se verifica ninguna entrega desde aquí.</p>${button('ceremony-confirm','Representar Fragmento III')}`);break;case 'ceremony-confirm':s.ceremony=true;save();close();break;
case 'copy':try{await navigator.clipboard.writeText(recordText());$('toast').textContent='Registro copiado.';$('toast').hidden=false;}catch(e){$('export-text').focus();$('export-text').select();}break;
case 'download':{const u=URL.createObjectURL(new Blob(['\ufeff'+recordText()],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='Registro_El_Templado_entre_Pares.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),10000);break;}
case 'fullscreen':document.documentElement.requestFullscreen?.().catch(()=>{});break;case 'reset-ask':modal('Reiniciar esta misión',`<p>Se borrará solo este borrador del dispositivo. Conserva primero el registro.</p>${button('reset','Reiniciar')}${button('record','Ver registro antes','',true)}`);break;case 'reset':s=fresh();flash='';save();go(0);break;}});
$('previous').addEventListener('click',()=>go(s.page-1));$('next').addEventListener('click',()=>s.page===N-1?record():go(s.page+1));$('modal').addEventListener('cancel',e=>{e.preventDefault();close();});document.addEventListener('keydown',e=>{if($('modal').open||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;if(e.key==='ArrowRight')go(s.page+1);if(e.key==='ArrowLeft')go(s.page-1);});const h=location.hash.match(/pantalla-(\d+)/);if(h&&Number(h[1])>=1&&Number(h[1])<=N)s.page=Number(h[1])-1;render();
})();

